+// Sales from the till. Each dish sold uses one portion of its recipe; the
+// stock goes through the ledger with the ref `sale:<ticket>`. A ticket is
+// imported once, and a file of sales is all or nothing (docs/DATA.md).
+import { AppError } from "../errors.js";
+import { dayOf } from "../dates.js";
+import { consume } from "./batches.js";
+import { getItem, listItems, onHand } from "./items.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+const round3 = (n) => Math.round(n * 1000) / 1000;
+
+// Ingredient quantities for `qty` portions of a dish's recipe.
+function dishNeeds(store, dishId, qty) {
+  const dish = (store.data.dishes ?? []).find((d) => d.id === dishId);
+  if (!dish) return null;
+  return scaled(getRecipe(store, dish.recipeId), qty).filter((n) => n.qty > 0);
+}
+
+/**
+ * Records sale lines ({ row, ticket, soldAt, dishId, qty }) and consumes their ingredients; tickets already recorded are skipped.
+ * Checks every line first: an unknown dish (bad_request) or an item running out (sale_not_enough_stock) names the row and changes nothing.
+ */
+export function recordSales(store, lines) {
+  const known = new Set((store.data.sales ?? []).map((s) => s.ticket));
+  const needed = new Map();
+  const tickets = new Map();
+  for (const line of lines) {
+    const needs = dishNeeds(store, line.dishId, line.qty);
+    if (!needs) throw new AppError("bad_request", { reason: `row ${line.row}: unknown dish ${line.dishId}` });
+    if (known.has(line.ticket)) continue;
+    for (const n of needs) {
+      const item = getItem(store, n.itemId);
+      const total = round3((needed.get(n.itemId) ?? 0) + n.qty);
+      const available = round3(onHand(store, n.itemId));
+      if (total > available)
+        throw new AppError("sale_not_enough_stock", { row: line.row, item: item.name, available: round3(available - (total - n.qty)), unit: item.unit });
+      needed.set(n.itemId, total);
+    }
+    const list = tickets.get(line.ticket) ?? [];
+    list.push({ ...line, needs });
+    tickets.set(line.ticket, list);
+  }
+  let dishes = 0;
+  store.data.sales ??= [];
+  for (const [ticket, list] of tickets) {
+    // One consumption per item and instant, so a batch gets one movement.
+    const uses = new Map();
+    for (const line of list) {
+      store.data.sales.push({ id: store.nextId("sale"), ticket, soldAt: line.soldAt, dishId: line.dishId, qty: line.qty });
+      dishes += line.qty;
+      for (const n of line.needs) {
+        const key = `${line.soldAt} ${n.itemId}`;
+        const use = uses.get(key) ?? { itemId: n.itemId, at: line.soldAt, qty: 0 };
+        use.qty = round3(use.qty + n.qty);
+        uses.set(key, use);
+      }
+    }
+    for (const use of uses.values()) consume(store, use.itemId, use.qty, { at: use.at, ref: `sale:${ticket}` });
+  }
+  return { tickets: tickets.size, dishes };
+}
+
+/**
+ * Variance per item between two days (inclusive): theoretical use from the sales sold in those days,
+ * actual use from every "consume" movement, and the difference (actual minus theoretical).
+ */
+export function varianceReport(store, from, to) {
+  const inRange = (instant) => {
+    const day = dayOf(instant);
+    return day >= from && day <= to;
+  };
+  const theoretical = new Map();
+  for (const sale of store.data.sales ?? []) {
+    if (!inRange(sale.soldAt)) continue;
+    for (const n of dishNeeds(store, sale.dishId, sale.qty) ?? [])
+      theoretical.set(n.itemId, round3((theoretical.get(n.itemId) ?? 0) + n.qty));
+  }
+  const batchItem = new Map(store.data.batches.map((b) => [b.id, b.itemId]));
+  const actual = new Map();
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || !batchItem.has(m.batchId) || !inRange(m.at)) continue;
+    const itemId = batchItem.get(m.batchId);
+    actual.set(itemId, round3((actual.get(itemId) ?? 0) + m.qty));
+  }
+  return listItems(store)
+    .map((item) => {
+      const t = theoretical.get(item.id) ?? 0;
+      const a = actual.get(item.id) ?? 0;
+      return { itemId: item.id, name: item.name, unit: item.unit, theoretical: t, actual: a, difference: round3(a - t) };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0);
+}
